def is_sum_free(A):
    """Checks if a set A contains x, y, z such that x + y = z, where x, y, z are in A."""
    elements = list(A)
    for x in elements:
        for y in elements:
            s = x + y
            if s in elements:
                # Found x + y = z, where z = s
                return False
    return True

S = {1, 10}
subsets = []
# Generate all non-empty subsets of S
from itertools import combinations
for i in range(1, len(S) + 1):
    for subset_tuple in combinations(S, i):
        A = set(subset_tuple)
        subsets.append(A)

print("Checking subsets for the sum-triple property (x+y=z):")
for A in subsets:
    safe = is_sum_free(A)
    print(f"Subset {A}: Sum-free? {safe}")

# Check partitions of S
# m=1: {{1, 10}}
print("\nChecking m=1 partition:")
A1 = S
safe1 = is_sum_free(A1)
print(f"Partition {{ {A1} }}: Safe? {safe1}")

# m=2: {{1}, {10}}
print("\nChecking m=2 partition:")
A2a = {1}
A2b = {10}
safe2a = is_sum_free(A2a)
safe2b = is_sum_free(A2b)
print(f"Partition {{ {A2a}, {A2b} }}: Safe? {safe2a} and {safe2b}")

